exempt = (input('exempt_assets') || {})['CKV_AWS_379'] || []

control 'CKV_AWS_379' do
  title 'Ensure AWS S3 bucket is configured with secure data transport policy'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_s3_bucket resources that actually exist, read through the stock
    inspec-aws aws_s3_bucket resource.
  DESC

  desc 'rationale', <<~RATIONALE
    Without a policy denying aws:SecureTransport=false, an unencrypted
    request is accepted rather than refused, and TLS becomes a client-side
    choice.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: Ensure AWS S3 bucket is configured with secure data
    transport policy
  CHECK

  desc 'fix', <<~'FIX'
    See https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/s3_bucket_acl
  FIX

  tag checkov_id:            'CKV_AWS_379'
  tag checkov_category:      'NETWORKING'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'custom'
  tag tf_resources:          %w[aws_s3_bucket_acl]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs'
  tag nist:                  ['SC-8', 'SC-8 (1)']
  tag nist_r4:               ['SC-8', 'SC-8 (1)']
  tag cci:                   ['CCI-002418', 'CCI-002421']
  tag ksi:                   ['KSI-SVC-CET']
  tag severity:              'medium'
  tag severity_source:       'assessed'
  tag implementation_status: 'implemented'

  # Enumerated at control scope, then each asset asserted on its own. The
  # resource is an ARGUMENT to `describe`, which evaluates on the control --
  # calling it inside the block would defer it into the example.
  ids = aws_s3_buckets.bucket_names
  in_scope = ids.reject { |id| checkov_exempt?(id: id, type: 'aws_s3_bucket', rules: exempt) }

  applicable = !in_scope.empty?
  impact 0.5
  impact 0.0 unless applicable
  only_if('no aws_s3_bucket in scope') { applicable }

  in_scope.each do |id|
    describe aws_s3_bucket(bucket_name: id) do
      its('has_secure_transport_enabled?') { should eq true }
    end
  end
end
